/**
 * Data Loader - Handles data management
 * Loads game data from embedded GAME_DATA object in gameData.js
 * The GAME_DATA object is auto-generated by BuildData.bat from CSV files
 */
class DataLoader {
    constructor() {
        this.items = {};
        this.facilities = {};
        this.upgradeTree = {};
        this.recipeData = null;
        this.productionData = null;
        this.tradingData = null;
        this.gameConfig = {};
        this.productAreas = {};
        this.workerNames = [];
        this.workerGrades = [];
        this.workerUpgrades = {};
        this.workerLevels = {}; // { level: { expRequired, maxLevelByGrade } }
        this.tradingUpgrades = {}; // { level: { cooltime, maxQueueSlots, requirements } }
        this.tradingRegions = {}; // { regionId: { id, name } }
        this.tradingRegionUpgrades = {}; // { regionId: { level: { level, exp, orderList } } }
        this.tradingOrders = {}; // { orderId: { grade, credit, required, reward } }
        this.processUpgrades = {}; // { level: { level, processList } }
        this.itemProcessingLevels = {}; // { itemId: minLevel } - Cached minimum processing level for each item
        this.stashUpgrades = {}; // { level: { level, capacity } }
    }

    /**
     * Load all data from embedded GAME_DATA object
     * @returns {Promise} Resolves when all data is loaded
     */
    async loadAllData() {
        try {
            // Check if GAME_DATA is available
            if (typeof GAME_DATA === 'undefined') {
                throw new Error('GAME_DATA object not found. Make sure gameData.js is loaded before this script.');
            }

            // Group all data loading logs
            console.groupCollapsed('Loading Game Data');

            // Load all data from GAME_DATA object
            this.loadItems();
            this.loadFacilities();
            this.loadUpgrades();
            this.loadGameConfig();
            this.loadProduction();
            this.loadRecipes();
            this.loadTrading();
            this.loadProductAreas();
            this.loadWorkerData();
            this.loadWorkerLevels();
            this.loadTradingUpgrades();
            this.loadTradingRegions();
            this.loadTradingRegionUpgrades();
            this.loadTradingOrders();
            this.loadProcessUpgrades();
            this.loadStashUpgrades();
            this.buildProcessingLevelCache();

            console.log('All data loaded successfully from embedded GAME_DATA');
            console.groupEnd();
            return true;
        } catch (error) {
            console.error('Error loading data:', error);
            console.groupEnd();
            return false;
        }
    }

    /**
     * Load items from GAME_DATA
     */
    loadItems() {
        try {
            if (!GAME_DATA.items || GAME_DATA.items.length === 0) {
                throw new Error('No items found in GAME_DATA');
            }

            for (const item of GAME_DATA.items) {
                if (!item.id || !item.name) {
                    console.warn('Skipping invalid item:', item);
                    continue;
                }

                this.items[item.id] = {
                    id: item.id,
                    name: item.name,
                    stacks: item.stacks || 999,
                    grade: item.grade || 'common',
                    type: item.type || 'Special'
                };
            }

            console.log(`Loaded ${Object.keys(this.items).length} items from GAME_DATA`);
        } catch (error) {
            console.error('Error loading items:', error);
            throw error;
        }
    }

    /**
     * Load facilities from GAME_DATA
     */
    loadFacilities() {
        try {
            if (!GAME_DATA.facilities || GAME_DATA.facilities.length === 0) {
                throw new Error('No facilities found in GAME_DATA');
            }

            for (const facility of GAME_DATA.facilities) {
                if (!facility.id || !facility.name) {
                    console.warn('Skipping invalid facility:', facility);
                    continue;
                }

                this.facilities[facility.id] = {
                    id: facility.id,
                    name: facility.name,
                    type: facility.type || 'default'
                };
            }

            console.log(`Loaded ${Object.keys(this.facilities).length} facilities from GAME_DATA`);
        } catch (error) {
            console.error('Error loading facilities:', error);
            throw error;
        }
    }

    /**
     * Load facility upgrades from GAME_DATA
     */
    loadUpgrades() {
        try {
            if (!GAME_DATA.upgradeTree || Object.keys(GAME_DATA.upgradeTree).length === 0) {
                throw new Error('No upgrade tree found in GAME_DATA');
            }

            // Simply copy the upgrade tree structure
            this.upgradeTree = { ...GAME_DATA.upgradeTree };

            console.log(`Loaded upgrade data for ${Object.keys(this.upgradeTree).length} facilities from GAME_DATA`);
        } catch (error) {
            console.error('Error loading upgrades:', error);
            throw error;
        }
    }

    /**
     * Load game configuration from GAME_DATA
     */
    loadGameConfig() {
        try {
            if (!GAME_DATA.config || Object.keys(GAME_DATA.config).length === 0) {
                throw new Error('No configuration found in GAME_DATA');
            }

            this.gameConfig = { ...GAME_DATA.config };

            console.log('Loaded game configuration from GAME_DATA');
        } catch (error) {
            console.error('Error loading game configuration:', error);
            throw error;
        }
    }

    /**
     * Load production data from GAME_DATA
     */
    loadProduction() {
        try {
            if (!GAME_DATA.production || Object.keys(GAME_DATA.production).length === 0) {
                throw new Error('No production data found in GAME_DATA');
            }

            this.productionData = { ...GAME_DATA.production };

            console.log(`Loaded ${Object.keys(this.productionData).length} production facilities from GAME_DATA`);
        } catch (error) {
            console.error('Error loading production data:', error);
            throw error;
        }
    }

    /**
     * Load recipes from GAME_DATA
     */
    loadRecipes() {
        try {
            if (!GAME_DATA.recipes || Object.keys(GAME_DATA.recipes).length === 0) {
                throw new Error('No recipes found in GAME_DATA');
            }

            this.recipeData = { ...GAME_DATA.recipes };

            console.log(`Loaded ${Object.keys(this.recipeData).length} recipes from GAME_DATA`);
        } catch (error) {
            console.error('Error loading recipes:', error);
            throw error;
        }
    }

    /**
     * Load trading prices from GAME_DATA
     */
    loadTrading() {
        try {
            if (!GAME_DATA.trading || Object.keys(GAME_DATA.trading).length === 0) {
                throw new Error('No trading prices found in GAME_DATA');
            }

            this.tradingData = { ...GAME_DATA.trading };

            console.log(`Loaded ${Object.keys(this.tradingData).length} trading prices from GAME_DATA`);
        } catch (error) {
            console.error('Error loading trading prices:', error);
            throw error;
        }
    }

    /**
     * Load product areas from GAME_DATA
     */
    loadProductAreas() {
        try {
            if (!GAME_DATA.productAreas || GAME_DATA.productAreas.length === 0) {
                console.warn('No product areas found in GAME_DATA');
                return;
            }

            for (const area of GAME_DATA.productAreas) {
                if (!area.id) {
                    console.warn('Skipping invalid product area (missing id):', area);
                    continue;
                }

                // Parse productItem JSON if it's a string
                let productItem = area.productItem;
                if (typeof productItem === 'string') {
                    try {
                        productItem = JSON.parse(productItem);
                    } catch (e) {
                        console.warn('Failed to parse productItem JSON for area:', area.id, e);
                    }
                }

                // Parse requiredStat JSON if it's a string, or ensure it's an array
                let requiredStat = area.requiredStat || [];
                if (typeof requiredStat === 'string') {
                    try {
                        requiredStat = JSON.parse(requiredStat);
                    } catch (e) {
                        console.warn('Failed to parse requiredStat JSON for area:', area.id, e);
                        requiredStat = [];
                    }
                }
                // Ensure it's always an array (handle case where it might be wrapped in an object)
                if (!Array.isArray(requiredStat)) {
                    requiredStat = [];
                }

                this.productAreas[area.id] = {
                    id: area.id,
                    gridX: parseInt(area.gridX) || 1,
                    gridY: parseInt(area.gridY) || 1,
                    productItem: productItem,
                    cooltime: parseInt(area.cooltime) || 10,
                    workers: parseInt(area.workers) || 0,
                    requiredStat: requiredStat
                };
            }

            console.log(`Loaded ${Object.keys(this.productAreas).length} product areas from GAME_DATA`);
        } catch (error) {
            console.error('Error loading product areas:', error);
        }
    }

    /**
     * Get item by ID
     */
    getItem(itemId) {
        return this.items[itemId] || null;
    }

    /**
     * Get facility by ID
     */
    getFacility(facilityId) {
        return this.facilities[facilityId] || null;
    }

    /**
     * Get upgrade cost for a facility at a specific level
     */
    getUpgradeCost(facilityId, level) {
        if (!this.upgradeTree[facilityId] || !this.upgradeTree[facilityId][level]) {
            return null;
        }
        return this.upgradeTree[facilityId][level];
    }

    /**
     * Get all items
     */
    getAllItems() {
        return { ...this.items };
    }

    /**
     * Get all facilities
     */
    getAllFacilities() {
        return { ...this.facilities };
    }

    /**
     * Get recipe for an item
     */
    getRecipe(itemId) {
        return this.recipeData ? this.recipeData[itemId] : null;
    }

    /**
     * Get production data for a facility
     */
    getProduction(facilityId) {
        return this.productionData ? this.productionData[facilityId] : null;
    }

    /**
     * Get trading price for an item
     */
    getTradingPrice(itemId) {
        return this.tradingData ? this.tradingData[itemId] : null;
    }

    /**
     * Get game configuration value
     */
    getConfig(key) {
        return this.gameConfig[key] !== undefined ? this.gameConfig[key] : null;
    }

    /**
     * Get all product areas available for a facility at a specific level
     * Returns array of {areaId, areaCount} for areas available at this level
     */
    getAvailableProductAreas(facilityId, level) {
        const upgrade = this.getUpgradeCost(facilityId, level);
        if (!upgrade || !upgrade.productAreas) {
            return [];
        }

        // Parse productAreas JSON if it's a string
        let productAreas = upgrade.productAreas;
        if (typeof productAreas === 'string') {
            try {
                productAreas = JSON.parse(productAreas);
            } catch (e) {
                console.warn(`Failed to parse productAreas JSON for ${facilityId} level ${level}:`, e);
                return [];
            }
        }

        // Convert to array of {areaId, areaCount} objects
        return Object.entries(productAreas).map(([areaId, areaCount]) => ({
            areaId: areaId,
            areaCount: areaCount
        }));
    }

    /**
     * Get all product areas for a facility (all versions, regardless of level)
     * Used for UI reference purposes
     */
    getProductAreasByFacility(facilityId) {
        // This now needs to be called with context of facility level
        // For backwards compatibility, return all areas with this facility prefix
        return Object.values(this.productAreas);
    }

    /**
     * Get product area by ID
     */
    getProductArea(areaId) {
        return this.productAreas[areaId] || null;
    }

    /**
     * Get grid dimensions for a facility at a specific level
     * Grid width is fixed at 6 columns
     * Grid height is determined by the Grid value (number of rows)
     */
    getGridDimensions(facilityId, level) {
        const upgrade = this.getUpgradeCost(facilityId, level);
        const gridHeight = upgrade && upgrade.Grid ? parseInt(upgrade.Grid) : 10;
        return { x: 6, y: gridHeight }; // Fixed 6 columns, dynamic rows
    }

    /**
     * Load worker-related data from GAME_DATA
     */
    loadWorkerData() {
        try {
            // Load worker names
            if (GAME_DATA.workerNames) {
                this.workerNames = [...GAME_DATA.workerNames];
            }

            // Load worker grades
            if (GAME_DATA.workerGrades) {
                this.workerGrades = [...GAME_DATA.workerGrades];
            }

            // Load worker upgrades
            if (GAME_DATA.workerUpgrades) {
                this.workerUpgrades = { ...GAME_DATA.workerUpgrades };
            }

            console.log('Loaded worker data from GAME_DATA');
        } catch (error) {
            console.error('Error loading worker data:', error);
        }
    }

    /**
     * Get random worker name
     */
    getRandomWorkerName() {
        if (this.workerNames.length === 0) {
            return "Noname";
        }
        return this.workerNames[Math.floor(Math.random() * this.workerNames.length)];
    }

    /**
     * Get random worker grade (weighted random selection)
     */
    getRandomWorkerGrade() {
        if (this.workerGrades.length === 0) {
            return null;
        }

        const totalWeight = this.workerGrades.reduce((sum, grade) => sum + grade.weight, 0);
        let random = Math.random() * totalWeight;

        for (const grade of this.workerGrades) {
            random -= grade.weight;
            if (random <= 0) {
                return grade;
            }
        }

        return this.workerGrades[0];
    }

    /**
     * Get worker grade by ID
     */
    getWorkerGrade(gradeId) {
        return this.workerGrades.find(g => g.id === gradeId) || null;
    }

    /**
     * Get worker upgrade data for lodge level
     */
    getWorkerUpgrade(level) {
        return this.workerUpgrades[level.toString()] || null;
    }

    /**
     * Get random worker grade based on lodge level
     * Uses level-based weights from workerUpgrade data
     * @param {number} lodgeLevel - Current level of the Worker's Lodge
     * @returns {object} Selected worker grade
     */
    getRandomWorkerGradeByLevel(lodgeLevel) {
        const upgradeData = this.getWorkerUpgrade(lodgeLevel);

        // If no upgrade data or gradeWeight, fall back to old weighted system
        if (!upgradeData || !upgradeData.gradeWeight) {
            return this.getRandomWorkerGrade();
        }

        // Parse gradeWeight JSON if it's a string
        let gradeWeights = upgradeData.gradeWeight;
        if (typeof gradeWeights === 'string') {
            try {
                gradeWeights = JSON.parse(gradeWeights);
            } catch (e) {
                console.warn(`Failed to parse gradeWeight JSON for lodge level ${lodgeLevel}:`, e);
                return this.getRandomWorkerGrade(); // Fallback
            }
        }

        // Ensure gradeWeights is an array
        if (!Array.isArray(gradeWeights) || gradeWeights.length === 0) {
            return this.getRandomWorkerGrade(); // Fallback
        }

        // Calculate total weight
        const totalWeight = gradeWeights.reduce((sum, item) => sum + item.weight, 0);
        if (totalWeight <= 0) {
            return this.getRandomWorkerGrade(); // Fallback
        }

        // Select grade based on weighted probability
        let random = Math.random() * totalWeight;
        for (const item of gradeWeights) {
            random -= item.weight;
            if (random <= 0) {
                // Find the grade object matching this grade ID
                const grade = this.getWorkerGrade(item.grade);
                if (grade) {
                    return grade;
                }
            }
        }

        // Fallback: return the last grade in the weighted list
        const lastGrade = this.getWorkerGrade(gradeWeights[gradeWeights.length - 1].grade);
        return lastGrade || this.getRandomWorkerGrade();
    }

    /**
     * Calculate hiring cost for a worker
     */
    calculateHiringCost(grade, level) {
        if (!grade) return 0;
        return grade.baseGold + (grade.levelGold * level);
    }

    /**
     * Load worker level data from GAME_DATA
     */
    loadWorkerLevels() {
        try {
            if (!GAME_DATA.workerLevels) {
                console.warn('No worker level data found in GAME_DATA');
                return;
            }

            for (const levelData of GAME_DATA.workerLevels) {
                const level = parseInt(levelData.level);
                this.workerLevels[level] = {
                    level: level,
                    expRequired: parseInt(levelData.expRequired) || 0
                };
            }

            console.log(`Loaded worker level data for ${Object.keys(this.workerLevels).length} levels from GAME_DATA`);
        } catch (error) {
            console.error('Error loading worker levels:', error);
        }
    }

    /**
     * Get EXP required to reach a level
     */
    getExpRequiredForLevel(level) {
        if (!this.workerLevels[level]) {
            return 0;
        }
        return this.workerLevels[level].expRequired;
    }

    /**
     * Get max level for a worker grade
     */
    getMaxLevelForGrade(gradeId) {
        const grade = this.getWorkerGrade(gradeId);
        if (!grade) {
            console.warn(`[DATALOADER] Grade ${gradeId} not found in workerGrades`);
            return 1;
        }
        return grade.maxLevel;
    }

    /**
     * Check if worker has reached max level for their grade
     */
    isWorkerAtMaxLevel(worker) {
        const maxLevel = this.getMaxLevelForGrade(worker.grade);
        return worker.level >= maxLevel;
    }

    /**
     * Load trading upgrades from GAME_DATA
     */
    loadTradingUpgrades() {
        try {
            if (!GAME_DATA.tradingUpgrades || Object.keys(GAME_DATA.tradingUpgrades).length === 0) {
                console.warn('No trading upgrades found in GAME_DATA');
                return;
            }

            for (const [level, upgrade] of Object.entries(GAME_DATA.tradingUpgrades)) {
                if (!upgrade.level) {
                    console.warn('Skipping invalid trading upgrade (missing level):', upgrade);
                    continue;
                }

                // Parse requirements JSON if it's a string
                let requirements = upgrade.requirements || [];
                if (typeof requirements === 'string') {
                    try {
                        requirements = JSON.parse(requirements);
                    } catch (e) {
                        console.warn(`Failed to parse requirements JSON for trading upgrade level ${upgrade.level}:`, e);
                        requirements = [];
                    }
                }

                this.tradingUpgrades[parseInt(upgrade.level)] = {
                    level: parseInt(upgrade.level),
                    cooltime: parseInt(upgrade.cooltime) || 360,
                    maxQueueSlots: parseInt(upgrade.maxQueueSlots) || 3,
                    requirements: requirements
                };
            }

            console.log(`Loaded ${Object.keys(this.tradingUpgrades).length} trading upgrade levels from GAME_DATA`);
        } catch (error) {
            console.error('Error loading trading upgrades:', error);
        }
    }

    /**
     * Load trading regions from GAME_DATA
     */
    loadTradingRegions() {
        try {
            if (!GAME_DATA.tradingRegions || GAME_DATA.tradingRegions.length === 0) {
                console.warn('No trading regions found in GAME_DATA');
                return;
            }

            for (const region of GAME_DATA.tradingRegions) {
                if (!region.id) {
                    console.warn('Skipping invalid trading region (missing id):', region);
                    continue;
                }

                this.tradingRegions[region.id] = {
                    id: region.id,
                    name: region.name || region.id
                };
            }

            console.log(`Loaded ${Object.keys(this.tradingRegions).length} trading regions from GAME_DATA`);
        } catch (error) {
            console.error('Error loading trading regions:', error);
        }
    }

    /**
     * Load trading region upgrades from GAME_DATA
     */
    loadTradingRegionUpgrades() {
        try {
            if (!GAME_DATA.tradingRegionUpgrades || GAME_DATA.tradingRegionUpgrades.length === 0) {
                console.warn('No trading region upgrades found in GAME_DATA');
                return;
            }

            for (const upgrade of GAME_DATA.tradingRegionUpgrades) {
                if (!upgrade.id) {
                    console.warn('Skipping invalid trading region upgrade (missing id):', upgrade);
                    continue;
                }

                const regionId = upgrade.id;
                if (!this.tradingRegionUpgrades[regionId]) {
                    this.tradingRegionUpgrades[regionId] = {};
                }

                // Parse orderList JSON if it's a string
                let orderList = upgrade.orderList || [];
                if (typeof orderList === 'string') {
                    try {
                        orderList = JSON.parse(orderList);
                    } catch (e) {
                        console.warn(`Failed to parse orderList JSON for region upgrade ${regionId} level ${upgrade.level}:`, e);
                        orderList = [];
                    }
                }

                const level = parseInt(upgrade.level) || 1;
                this.tradingRegionUpgrades[regionId][level] = {
                    level: level,
                    exp: parseInt(upgrade.exp) || 1000,
                    orderList: orderList
                };
            }

            console.log(`Loaded trading region upgrades from GAME_DATA`);
        } catch (error) {
            console.error('Error loading trading region upgrades:', error);
        }
    }

    /**
     * Load trading orders from GAME_DATA
     */
    loadTradingOrders() {
        try {
            if (!GAME_DATA.tradingOrders || GAME_DATA.tradingOrders.length === 0) {
                console.warn('No trading orders found in GAME_DATA');
                return;
            }

            for (const order of GAME_DATA.tradingOrders) {
                if (!order.id) {
                    console.warn('Skipping invalid trading order (missing id):', order);
                    continue;
                }

                // Parse required JSON if it's a string
                let required = order.required || [];
                if (typeof required === 'string') {
                    try {
                        required = JSON.parse(required);
                    } catch (e) {
                        console.warn(`Failed to parse required JSON for order ${order.id}:`, e);
                        required = [];
                    }
                }

                // Parse reward JSON if it's a string
                let reward = order.reward || [];
                if (typeof reward === 'string') {
                    try {
                        reward = JSON.parse(reward);
                    } catch (e) {
                        console.warn(`Failed to parse reward JSON for order ${order.id}:`, e);
                        reward = [];
                    }
                }

                this.tradingOrders[order.id] = {
                    id: order.id,
                    grade: order.grade || 'Common',
                    credit: parseInt(order.credit) || 100,
                    required: required,
                    reward: reward
                };
            }

            console.log(`Loaded ${Object.keys(this.tradingOrders).length} trading orders from GAME_DATA`);
        } catch (error) {
            console.error('Error loading trading orders:', error);
        }
    }

    /**
     * Get trading upgrade by level
     */
    getTradingUpgrade(level) {
        return this.tradingUpgrades[level] || null;
    }


    /**
     * Load process upgrades from GAME_DATA
     */
    loadProcessUpgrades() {
        try {
            if (!GAME_DATA.processUpgrades || Object.keys(GAME_DATA.processUpgrades).length === 0) {
                console.warn('No process upgrades found in GAME_DATA');
                return;
            }

            for (const [level, upgrade] of Object.entries(GAME_DATA.processUpgrades)) {
                // Parse processList JSON if it's a string
                let processList = upgrade.processList || [];
                if (typeof processList === 'string') {
                    try {
                        processList = JSON.parse(processList);
                    } catch (e) {
                        console.warn(`Failed to parse processList JSON for level ${level}:`, e);
                        processList = [];
                    }
                }

                this.processUpgrades[level] = {
                    level: parseInt(level),
                    processList: processList
                };
            }

            console.log(`Loaded ${Object.keys(this.processUpgrades).length} process upgrade levels from GAME_DATA`);
        } catch (error) {
            console.error('Error loading process upgrades:', error);
        }
    }

    /**
     * Get process upgrade by level
     */
    getProcessUpgrade(level) {
        return this.processUpgrades[level] || null;
    }

    /**
     * Check if a recipe is unlocked at the given processing facility level
     */
    isRecipeUnlocked(recipeItemId, facilityLevel) {
        const upgrade = this.getProcessUpgrade(facilityLevel);
        if (!upgrade) return false;
        return upgrade.processList && upgrade.processList.includes(recipeItemId);
    }

    /**
     * Build a cache of minimum processing levels for each item (O(1) lookup optimization)
     * Iterates through process upgrade levels in ascending order and maps each item
     * to the FIRST level where it appears in the processList
     */
    buildProcessingLevelCache() {
        this.itemProcessingLevels = {};

        // Sort levels numerically and iterate in ascending order
        const sortedLevels = Object.keys(this.processUpgrades)
            .map(level => parseInt(level))
            .sort((a, b) => a - b);

        for (const level of sortedLevels) {
            const upgrade = this.processUpgrades[level];
            if (!upgrade || !upgrade.processList) continue;

            // For each item in this level's processList
            for (const itemId of upgrade.processList) {
                // Only store if this is the first level where the item appears
                if (!(itemId in this.itemProcessingLevels)) {
                    this.itemProcessingLevels[itemId] = level;
                }
            }
        }

        console.log(`Built processing level cache for ${Object.keys(this.itemProcessingLevels).length} items`);
    }

    /**
     * Get the minimum processing facility level required to craft an item
     * Returns null if the item is not craftable in the processing plant
     * O(1) lookup against pre-calculated cache
     */
    getItemProcessingLevel(itemId) {
        return this.itemProcessingLevels[itemId] || null;
    }

    /**
     * Get all trading regions
     * @returns {Array} Array of region objects {id, name}
     */
    getAllTradingRegions() {
        return GAME_DATA.tradingRegions || [];
    }

    /**
     * Get trading region by ID
     * @param {string} regionId - Region ID
     * @returns {Object} Region object with id and name
     */
    getTradingRegion(regionId) {
        const regions = GAME_DATA.tradingRegions || [];
        return regions.find(r => r.id === regionId);
    }

    /**
     * Get orders for a specific region and level from tradingRegionUpgrades
     * @param {string} regionId - Region ID
     * @param {number} level - Region level
     * @returns {Array} Array of order references {orderId, appearRate}
     */
    getOrdersForRegionLevel(regionId, level) {
        const upgradeData = GAME_DATA.tradingRegionUpgrades || [];
        const match = upgradeData.find(u => u.id === regionId && u.level === level);

        if (!match || !match.orderList) return [];

        try {
            let orderList = match.orderList;

            // Handle nested .value structure (from CSV parsing)
            if (orderList && typeof orderList === 'object' && !Array.isArray(orderList) && orderList.value) {
                orderList = orderList.value;
            }

            // Parse if it's a string
            if (typeof orderList === 'string') {
                orderList = JSON.parse(orderList);
            }

            return Array.isArray(orderList) ? orderList : [];
        } catch (e) {
            console.warn(`Failed to parse orderList for ${regionId} level ${level}:`, e);
            return [];
        }
    }

    /**
     * Get trading order by ID
     * @param {string} orderId - Order ID
     * @returns {Object} Order object
     */
    getTradingOrder(orderId) {
        const orders = GAME_DATA.tradingOrders || [];
        return orders.find(o => o.id === orderId) || null;
    }

    /**
     * Load stash upgrade data from GAME_DATA
     */
    loadStashUpgrades() {
        try {
            if (!GAME_DATA.stashUpgrades || Object.keys(GAME_DATA.stashUpgrades).length === 0) {
                console.warn('No stash upgrades found in GAME_DATA');
                return;
            }

            for (const [level, upgrade] of Object.entries(GAME_DATA.stashUpgrades)) {
                if (!upgrade.level) {
                    console.warn('Skipping invalid stash upgrade (missing level):', upgrade);
                    continue;
                }

                this.stashUpgrades[parseInt(upgrade.level)] = {
                    level: parseInt(upgrade.level),
                    capacity: parseInt(upgrade.capacity) || 0
                };
            }

            console.log(`Loaded ${Object.keys(this.stashUpgrades).length} stash upgrade levels from GAME_DATA`);
        } catch (error) {
            console.error('Error loading stash upgrades:', error);
        }
    }

    /**
     * Get stash upgrade by level
     * @param {number} level - Stash level
     * @returns {Object} Stash upgrade object {level, capacity}
     */
    getStashUpgrade(level) {
        return this.stashUpgrades[level] || null;
    }

    /**
     * Get stash capacity for a given level
     * @param {number} level - Stash level
     * @returns {number} Storage capacity
     */
    getStashCapacity(level) {
        const upgrade = this.getStashUpgrade(level);
        return upgrade ? upgrade.capacity : 0;
    }

    /**
     * Get trading region upgrade for a specific region and level
     * @param {string} regionId - Region ID
     * @param {number} level - Region level
     * @returns {Object} Region upgrade object
     */
    getTradingRegionUpgrade(regionId, level) {
        const upgrades = GAME_DATA.tradingRegionUpgrades || [];
        return upgrades.find(u => u.id === regionId && u.level === level) || null;
    }

    /**
     * Get experience required to advance from a level to the next level
     * @param {string} regionId - Region ID
     * @param {number} level - Region level
     * @returns {number} Experience required for the next level
     */
    getRegionLevelExp(regionId, level) {
        const upgrade = this.getTradingRegionUpgrade(regionId, level);
        return upgrade ? upgrade.exp : 1000;
    }

    /**
     * Get maximum level for a trading region
     * @param {string} regionId - Region ID
     * @returns {number} Maximum level available for this region
     */
    getTradingRegionMaxLevel(regionId) {
        const upgrades = GAME_DATA.tradingRegionUpgrades || [];
        const regionUpgrades = upgrades.filter(u => u.id === regionId);

        if (regionUpgrades.length === 0) {
            return 1; // Default to level 1 if no upgrades found
        }

        // Find the maximum level across all upgrades for this region
        return Math.max(...regionUpgrades.map(u => parseInt(u.level)));
    }
}

// Create global data loader instance
const dataLoader = new DataLoader();
